// Generates src/lib/leaflet-embed.ts so the map works with no internet and no CDN.
const fs = require('fs');
const path = require('path');
const dist = path.join(__dirname, '..', 'node_modules', 'leaflet', 'dist');
const js = fs.readFileSync(path.join(dist, 'leaflet.js'), 'utf8').replace(/\/\/# sourceMappingURL=.*$/m, '');
// The embedded runtime lives inside an HTML <script>, so it must never contain a closing script tag.
if (/<\/script/i.test(js)) throw new Error('leaflet.js contains </script');
// Marker icons are drawn with HTML (divIcon), so the image-based rules are not needed; keep the CSS as is.
const css = fs.readFileSync(path.join(dist, 'leaflet.css'), 'utf8');
const out = `// GENERATED by scripts/embed-leaflet.js from leaflet@${require('leaflet/package.json').version}. Do not edit.\nexport const LEAFLET_JS = ${JSON.stringify(js)};\nexport const LEAFLET_CSS = ${JSON.stringify(css)};\n`;
fs.writeFileSync(path.join(__dirname, '..', 'src', 'lib', 'leaflet-embed.ts'), out);
console.log('wrote leaflet-embed.ts', (out.length / 1024).toFixed(0) + ' KB');
